// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {IERC1271} from "@openzeppelin/contracts/interfaces/IERC1271.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MerkleProof} from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title Configurator
/// @author Michael Standen
/// @notice Owner-of-record for route and adapter administration, redeemable from a single signature.
/// @dev The owner signs one merkle root covering every configuration change across every chain. Each
/// leaf is one chain's atomic batch of calls, redeemable permissionlessly by any relayer against a
/// proof. This collapses a multisig round per administrative call into one round per rollout.
///
/// The signed digest deliberately omits `chainId` and `verifyingContract` from its EIP-712 domain: a
/// domain pinned to one chain would need one signature per chain, which is the cost this contract
/// exists to remove. `ConfigLeaf.chainId` and `ConfigLeaf.configurator` scope execution instead, so a
/// leaf can only run on the chain and the deployment it was written for. The deployment goes in the
/// leaf rather than in `verifyingContract` because this contract does not sit at the same address
/// everywhere (Tron addresses come from TronBox's transaction-derived `CREATE`), and each chain's
/// leaf can name that chain's instance without splitting the signature.
///
/// The one-signature property only holds for a plain-key owner, whose ECDSA signature verifies
/// identically on every chain. ERC-1271 validity is chain-local, and a Safe binds `chainid` and its
/// own address into the `SafeMessage` it checks, so a Safe owner needs one signature per chain even
/// at the same address with the same signers.
///
/// A Tron-native multisig (account permissions) must never be the owner. The contract only sees a
/// codeless address, so it checks roots by ECDSA, and `ecrecover` knows nothing about account
/// permissions: the key the account was created from still recovers to it and can sign any root
/// alone, bypassing the threshold. On Tron, have the multisig hold the roles directly, or give the
/// Configurator a plain-key owner if a single key is the intended model.
///
/// Authority here is the union of every role this contract holds on its targets. A leaf can call
/// anything, including `transferOwnership` on a target. Rotating this contract's own owner
/// invalidates every root the previous owner signed, so pending rollouts must be re-signed after one.
/// Rotation is two-step and renouncing is disabled: a mistyped owner or a renounce would strand the
/// authority over every target this contract holds, with no way back.
contract Configurator is Ownable2Step, ReentrancyGuard {
  // @notice One call to one target, as part of a leaf's atomic batch.
  // @param target The contract to call
  // @param data The calldata to send to `target`
  struct Call {
    address target;
    bytes data;
  }

  /// @notice One chain's atomic batch of calls, redeemable from a signed root.
  /// @param chainId The only chain this leaf may execute on
  /// @param configurator The only `Configurator` deployment this leaf may execute on
  /// @param nonce The chain's `nonce` at execution time; numbering is assigned when the root is built
  /// @param calls Executed in order, atomically
  struct ConfigLeaf {
    uint256 chainId;
    address configurator;
    uint256 nonce;
    Call[] calls;
  }

  /// @dev `EIP712Domain(string name,string version)`. Both `chainId` and `verifyingContract` are
  /// omitted so one signature covers every chain; EIP-712 permits any subset of domain fields.
  bytes32 private constant DOMAIN_TYPE_HASH = keccak256("EIP712Domain(string name,string version)");
  bytes32 private constant DOMAIN_NAME_HASH = keccak256("TrailsPdasConfigurator");
  bytes32 private constant DOMAIN_VERSION_HASH = keccak256("1");
  bytes32 private constant ROOT_TYPE_HASH = keccak256("ConfigRoot(bytes32 root)");

  /// @notice Nonce of the next leaf executable on this chain.
  /// @dev Sequential rather than a per-leaf executed flag: it fixes the order configuration applies
  /// in, and makes advancing past a leaf equivalent to cancelling it, so superseded leaves from old
  /// roots can never be redeemed late. Leaf numbering is an off-chain concern; this is the on-chain
  /// side of it. Read before building a root.
  ///
  /// Nonces are a play order, not a signing order, so a leaf that cannot execute is unblocked by
  /// signing a new root holding a leaf at the same nonce. Whichever is played first consumes the
  /// nonce and strands the other. A leaf must hold at least one call, so the do-nothing leaf is a
  /// single call with empty calldata to an EOA.
  uint256 public nonce;

  /// @notice Roots that can no longer be played on this chain, either redeemed or withdrawn.
  /// @dev Consumption is per chain, and a root is spent by the first leaf of it that executes here.
  /// A root therefore carries at most one leaf per chain, which is what it means for a leaf to be
  /// that chain's batch. Paired with the nonce this closes replay from both sides: the nonce fixes
  /// what may execute next, this fixes what a given root may ever execute.
  mapping(bytes32 root => bool consumed) public rootConsumed;

  event ConfigExecuted(bytes32 indexed _root, bytes32 indexed _leafHash, uint256 _nonce);
  event RootRevoked(bytes32 indexed _root);

  error InvalidChainId(uint256 _expected, uint256 _actual);
  error InvalidConfigurator(address _expected, address _actual);
  error InvalidNonce(uint256 _expected, uint256 _actual);
  error RootAlreadyConsumed(bytes32 _root);
  error InvalidSignature();
  error InvalidProof();
  error NoCalls();
  error TargetHasNoCode(address _target);
  error RenounceDisabled();

  /// @param _owner Signer of configuration roots
  constructor(address _owner) Ownable(_owner) {}

  /// @notice Executes one configuration leaf from an owner-signed root.
  /// @dev Permissionless: the signature and proof are the authorization, so any relayer can redeem a
  /// leaf. Calls run atomically, so the nonce advances only if all of them succeed.
  ///
  /// Non-reentrant, because a leaf's calls reach arbitrary targets under this contract's authority
  /// and must not re-enter to redeem a second leaf inside the first. A `transferOwnership` to a
  /// hostile contract, or a target that is later replaced, is enough to make that reachable.
  /// Guarded rather than relying on the nonce and consumed-root writes preceding the calls, so
  /// nothing depends on a future edit keeping that ordering.
  ///
  /// A call with calldata to an address without code reverts instead of succeeding as a no-op, so a
  /// leaf aimed at the wrong address (easy on Tron, where deployments differ from EVM) cannot consume
  /// the nonce and root while applying nothing. Empty calldata is still allowed to anything, which
  /// keeps the documented do-nothing leaf working.
  /// @param _root Merkle root the owner signed
  /// @param _leaf Leaf to execute
  /// @param _proof Merkle proof of `_leaf` under `_root`
  /// @param _signature Owner signature over `_root`, ECDSA or ERC-1271
  function updateConfig(bytes32 _root, ConfigLeaf calldata _leaf, bytes32[] calldata _proof, bytes calldata _signature)
    external
    nonReentrant
  {
    if (_leaf.chainId != block.chainid) {
      revert InvalidChainId(_leaf.chainId, block.chainid);
    }
    if (_leaf.configurator != address(this)) {
      revert InvalidConfigurator(_leaf.configurator, address(this));
    }
    if (_leaf.nonce != nonce) {
      revert InvalidNonce(nonce, _leaf.nonce);
    }
    if (_leaf.calls.length == 0) {
      revert NoCalls();
    }
    if (rootConsumed[_root]) {
      revert RootAlreadyConsumed(_root);
    }

    bytes32 leafHash = hashLeaf(_leaf);
    if (!MerkleProof.verifyCalldata(_proof, _root, leafHash)) {
      revert InvalidProof();
    }

    if (!_isValidOwnerSignature(rootDigest(_root), _signature)) {
      revert InvalidSignature();
    }

    nonce = _leaf.nonce + 1;
    rootConsumed[_root] = true;

    for (uint256 i = 0; i < _leaf.calls.length; i++) {
      Call calldata call = _leaf.calls[i];
      if (call.data.length != 0 && call.target.code.length == 0) {
        revert TargetHasNoCode(call.target);
      }
      (bool success, bytes memory result) = call.target.call(call.data);
      if (!success) {
        assembly ("memory-safe") {
          revert(add(result, 0x20), mload(result))
        }
      }
    }

    emit ConfigExecuted(_root, leafHash, _leaf.nonce);
  }

  /// @notice Withdraws a root on this chain, blocking its leaf if it has not run yet.
  /// @dev Owner transaction rather than a signed message: revocation is an emergency path where the
  /// owner is already able to act, and a redeemable revocation would itself be a standing
  /// authorization someone has to reason about. Cancels without advancing the nonce, leaving the
  /// sequence blocked at that leaf's number until a replacement leaf at the same nonce is played.
  function revokeRoot(bytes32 _root) external onlyOwner {
    rootConsumed[_root] = true;

    emit RootRevoked(_root);
  }

  /// @notice Disabled: renouncing would leave every target this contract administers without an admin.
  function renounceOwnership() public view override onlyOwner {
    revert RenounceDisabled();
  }

  /// @notice The digest the owner signs for `_root`.
  function rootDigest(bytes32 _root) public pure returns (bytes32) {
    bytes32 domainSeparator = keccak256(abi.encode(DOMAIN_TYPE_HASH, DOMAIN_NAME_HASH, DOMAIN_VERSION_HASH));
    bytes32 structHash = keccak256(abi.encode(ROOT_TYPE_HASH, _root));

    return keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
  }

  /// @notice Whether `_signature` is the owner's over `_digest`, by ECDSA or ERC-1271.
  /// @dev ECDSA is tried first regardless of the owner's code, then ERC-1271, the same order as
  /// `SignatureChecker`. Gating ECDSA on empty code would lock out an EOA owner once it adopts an
  /// EIP-7702 delegation, whose delegate need not accept the key's plain signature over `_digest`.
  /// A contract owner has no key, so ECDSA can never recover to it and the order changes nothing there.
  ///
  /// @dev Hand-rolled rather than OpenZeppelin's `SignatureChecker`, which is unusable here: it
  /// reaches ERC-1271 through `mcopy`, and pulls in `Bytes` for ERC-7913 which does the same.
  /// `mcopy` is Cancun-only and `solc` rejects it for Tron's Shanghai target at compile time, for
  /// the whole file, whether or not the offending function is ever called. `ECDSA` itself is clean.
  function _isValidOwnerSignature(bytes32 _digest, bytes calldata _signature) private view returns (bool) {
    address currentOwner = owner();

    (address recovered, ECDSA.RecoverError err,) = ECDSA.tryRecoverCalldata(_digest, _signature);
    if (err == ECDSA.RecoverError.NoError && recovered == currentOwner) {
      return true;
    }
    if (currentOwner.code.length == 0) {
      return false;
    }

    (bool success, bytes memory result) =
      currentOwner.staticcall(abi.encodeCall(IERC1271.isValidSignature, (_digest, _signature)));

    return success && result.length >= 32 && abi.decode(result, (bytes4)) == IERC1271.isValidSignature.selector;
  }

  /// @notice The merkle leaf value for `_leaf`.
  /// @dev Hashed twice so no leaf value can collide with an internal node, which is a 64-byte
  /// preimage; a single hash would let a proof pass off an internal node as a leaf.
  function hashLeaf(ConfigLeaf calldata _leaf) public pure returns (bytes32) {
    return keccak256(bytes.concat(keccak256(abi.encode(_leaf))));
  }
}

